#!/usr/bin/env bash
# Builds, strips and installs Escargot Native into the user's XDG directories.
set -euo pipefail
cd "$(dirname "$0")"

export CARGO_BUILD_JOBS="${CARGO_BUILD_JOBS:-4}"
cargo build -j "$CARGO_BUILD_JOBS"

BIN_DIR="$HOME/.local/bin"
DATA_HOME="${XDG_DATA_HOME:-$HOME/.local/share}"
DATA_DIR="$DATA_HOME/escargot-native"
APP_DIR="$DATA_HOME/applications"
ICON_DIR="$DATA_HOME/icons/hicolor/256x256/apps"

mkdir -p "$BIN_DIR" "$DATA_DIR/assets" "$APP_DIR" "$ICON_DIR"

# Keep debug info out of the launcher binary while preserving the optimized
# code generated by the dev profile.
strip --strip-unneeded target/debug/escargot-native -o "$BIN_DIR/escargot-native"
chmod 755 "$BIN_DIR/escargot-native"
strip --strip-unneeded target/debug/escargot-webview -o "$BIN_DIR/escargot-webview"
chmod 755 "$BIN_DIR/escargot-webview"
ln -sf escargot-native "$BIN_DIR/msn"

rm -rf "$DATA_DIR/assets/img" "$DATA_DIR/assets/emoticons" "$DATA_DIR/assets/sounds" "$DATA_DIR/assets/wallpapers" "$DATA_DIR/assets/games"
cp -r assets/img assets/emoticons assets/sounds assets/wallpapers assets/games "$DATA_DIR/assets/"

if command -v magick >/dev/null 2>&1; then
    magick assets/icon.png -resize 256x256 "$ICON_DIR/escargot-native.png"
else
    cp assets/icon.png "$ICON_DIR/escargot-native.png"
fi

cat > "$APP_DIR/escargot-native.desktop" <<EOF
[Desktop Entry]
Type=Application
Version=1.0
Name=MSN Messenger
GenericName=Instant Messenger
Comment=Native MSN Messenger 7.5 for the Escargot network
Exec=$BIN_DIR/escargot-native
Icon=$ICON_DIR/escargot-native.png
Terminal=false
Categories=Network;InstantMessaging;
Keywords=msn;messenger;escargot;chat;linux;
StartupNotify=true
StartupWMClass=escargot-native-login
X-GNOME-UsesNotifications=true
EOF
chmod 644 "$APP_DIR/escargot-native.desktop"



command -v update-desktop-database >/dev/null 2>&1 \
    && update-desktop-database "$APP_DIR" >/dev/null 2>&1 || true
command -v gtk-update-icon-cache >/dev/null 2>&1 \
    && gtk-update-icon-cache -f -t "$DATA_HOME/icons/hicolor" >/dev/null 2>&1 || true

echo "installed: $BIN_DIR/escargot-native"
echo "command:   msn"
echo "launcher:  MSN Messenger"
